public function assignTentor(QualifixTicket $ticket): ?StaffProfile
{
    $candidates = StaffProfile::active()
        ->whereHas('scheduleRules', function ($q) use ($ticket) {
            $q->where('class_group_id', $ticket->class_group_id)
              ->where('subject_id', $ticket->subject_id);
