        ->withCount(['qualificTickets as active_count' => function ($q) {
            $q->where('status', '!=', 'selesai');
        }])
        ->orderBy('active_count')
        ->orderBy('full_name_with_title')
        ->first();

    if ($candidates === null) {
        $candidates = StaffProfile::active()
            ->withCount(['qualificTickets as active_count' => function ($q) {
                $q->where('status', '!=', 'selesai');
            }])
            ->orderBy('active_count')
            ->orderBy('full_name_with_title')
            ->first();
    }

    if ($candidates === null) {
        return null;
    }

    $ticket->staff()->attach($candidates->id, ['assigned_at' => now(), 'assigned_by' => auth()->id()]);
    return $candidates;
}
