<script>
(() => {
    const modal = document.getElementById('qualifix-ajukan-modal');
    const form = modal?.querySelector('[data-ajukan-form]');
    const subjectInput = document.getElementById('ajukan-subject-id');
    const fileInput = document.getElementById('ajukan-files');
    const fileList = document.getElementById('ajukan-file-list');
    let lastTrigger = null;

    const open = (trigger) => {
        lastTrigger = trigger;
        modal.classList.remove('hidden');
        document.body.style.overflow = 'hidden';
        modal.focus();
    };

    const close = () => {
        if (modal.classList.contains('hidden')) return;
        modal.classList.add('hidden');
        document.body.style.overflow = '';
        if (lastTrigger) lastTrigger.focus();
    };

    document.addEventListener('click', (e) => {
        if (e.target.closest('[data-qualifix-ajukan-open]')) {
            open(e.target.closest('[data-qualifix-ajukan-open]'));
            return;
        }
        if (e.target.closest('[data-ajukan-close]')) {
            close();
            return;
        }
        const option = e.target.closest('[data-ajukan-option]');
        if (option) {
            const subjectId = option.getAttribute('data-subject-id');
            modal.querySelectorAll('[data-ajukan-option]').forEach((btn) => {
                const selected = btn === option;
                btn.setAttribute('aria-checked', selected ? 'true' : 'false');
                btn.classList.toggle('border-ember-300', selected);
                btn.classList.toggle('bg-ember-50', selected);
                btn.classList.toggle('text-ember-700', selected);
                btn.classList.toggle('border-bark-200', !selected);
                btn.classList.toggle('bg-white', !selected);
                btn.classList.toggle('text-bark-500', !selected);
            });
            if (subjectInput) subjectInput.value = subjectId;
            return;
        }
        if (e.target.closest('[data-ajukan-dropzone]') && fileInput) {
            fileInput.click();
            return;
        }
    });

    if (fileInput && fileList) {
        fileInput.addEventListener('change', () => {
            fileList.innerHTML = '';
            Array.from(fileInput.files).forEach((file) => {
                const tag = document.createElement('span');
                tag.className = 'flex items-center gap-1 rounded-md border border-bark-200 bg-bark-50 px-2.5 py-1.5 text-[11px] font-medium text-bark-700';
                tag.textContent = file.name + ' (' + Math.round(file.size / 1024) + ' KB)';
                fileList.appendChild(tag);
            });
        });
    }

    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') close();
    });
})();
</script>

