private function seedKlinik(Student $student, int $subjectId, int $classGroupId): void
{
    $daftar = [
        ['ticket_number' => 'KPR-DEMO-0001', 'title' => 'Cara cepat limit bentuk 0/0', 'question' => 'Untuk soal limit aljabar bentuk 0/0, kapan pakai L\'Hopital dan kapan pakai pemfaktoran?', 'status' => 'selesai', 'resolved' => true],
        ['ticket_number' => 'KPR-DEMO-0002', 'title' => 'Beda substitusi dan parsial', 'question' => 'Bagaimana menentukan integral substitusi atau parsial saat soal tidak diberi petunjuk?', 'status' => 'menunggu_tentor', 'resolved' => false],
    ];

    $tentor = StaffProfile::active()->first();

    foreach ($daftar as $item) {
        $ticket = QualifixTicket::query()->updateOrCreate(
            ['ticket_number' => $item['ticket_number']],
            [
                'student_id' => $student->id,
                'subject_id' => $subjectId,
                'class_group_id' => $classGroupId,
                'title' => $item['title'],
                'question' => $item['question'],
                'status' => $item['status'],
                'submitted_at' => now()->subDays(3),
                'resolved_at' => $item['resolved'] ? now()->subDays(2) : null,
            ],
        );

        // Tugaskan tentor pendamping (jika ada) agar panel tentor tidak kosong saat demo.
        if ($tentor !== null) {
            $ticket->staff()->attach($tentor->id, [
                'assigned_at' => now()->subDays(3),
            ]);
        }

        // Buat contoh jawaban untuk tiket yang sudah selesai.
        if ($item['resolved'] && $tentor !== null) {
            QualifixAnswer::query()->updateOrCreate(
                ['ticket_id' => $ticket->id, 'staff_id' => $tentor->id],
                [
                    'body' => 'Jawaban contoh: lakukan pemfaktoran terlebih dahulu, baru setelah itu terapkan L\'Hopital jika masih berbentuk 0/0.',
                    'status' => 'terkirim',
                    'sent_at' => now()->subDays(2),
                ],
            );
        }
    }
}

