function req(string $method, string $uri, array $params = []): array
{
    $session = app('session.store');
    $session->start();

    $request = Request::create($uri, $method, $params);
    $request->setLaravelSession($session);

    // Token CSRF harus cocok dengan token sesi agar middleware memverifikasi.
    $params['_token'] = $session->token();
    $request = Request::create($uri, $method, $params);
    $request->setLaravelSession($session);

    $response = app()->handle($request);

    return [$response->getStatusCode(), $response->getContent()];
}

